package cn.reverie.obf;

import org.objectweb.asm.tree.ClassNode;

import java.nio.file.Path;
import java.util.List;

/** Shared pass context. */
public final class Ctx {
    public final Options opt;
    public final JarSet jar;
    public final Util.Rng rng;
    public Names names;
    public Mapping map;
    public final StringBuilder report = new StringBuilder();
    /** class internal names generated by the pipeline itself (pools, BSMs, integrity) */
    public final java.util.Set<String> generated = new java.util.HashSet<>();
    /** final internal names of classes whose bodies were encrypted+carried into assets/nocturne/c/*.dat by PackerPass */
    public final java.util.Set<String> packed = new java.util.HashSet<>();
    /** ORIGINAL internal names of classes registered in any *.mixins.json config (authoritative for mixin handling) */
    public final java.util.Set<String> mixinClasses = new java.util.HashSet<>();
    /** methods skipped by flow flattening, for the report */
    public int flowSkipped;

    public Ctx(Options opt, JarSet jar, List<Path> libs) {
        this.opt = opt;
        this.jar = jar;
        this.rng = new Util.Rng(opt.seed);
    }

    /** input jar (used as compile classpath for generated classes referencing renamed ones) */
    public Path inJar;
    /** directory holding the current (renamed) class files, for generated-class compilation */
    public Path classDumpDir;
    /** set by FlowPass: classes containing flattened methods */
    public java.util.Set<ClassNode> flowFlattened;

    public void log(String s) {
        report.append(s).append('\n');
    }

    public boolean isMixin(ClassNode cn) {
        return hasAnnotation(cn.visibleAnnotations, "Lorg/spongepowered/asm/mixin/Mixin;")
                || hasAnnotation(cn.invisibleAnnotations, "Lorg/spongepowered/asm/mixin/Mixin;");
    }

    /** true if the class lives in a keepPackages subtree (mixin 弱混: skip flow/ref transforms). */
    public boolean inKeepPackage(String internal) {
        for (String p : opt.keepPackages) {
            if (internal.equals(p) || internal.startsWith(p + "/")) return true;
        }
        return false;
    }

    private static boolean hasAnnotation(java.util.List<org.objectweb.asm.tree.AnnotationNode> list, String desc) {
        if (list == null) return false;
        for (var a : list) if (a.desc.equals(desc)) return true;
        return false;
    }

    /** true if the method carries any Mixin-framework annotation (@Overwrite/@Inject/@Shadow...) */
    public boolean hasMixinMethodAnnotation(org.objectweb.asm.tree.MethodNode mn) {
        return hasMixinAnnotation(mn.visibleAnnotations) || hasMixinAnnotation(mn.invisibleAnnotations);
    }

    public boolean hasMixinFieldAnnotation(org.objectweb.asm.tree.FieldNode fn) {
        return hasMixinAnnotation(fn.visibleAnnotations) || hasMixinAnnotation(fn.invisibleAnnotations);
    }

    private boolean hasMixinAnnotation(java.util.List<org.objectweb.asm.tree.AnnotationNode> list) {
        if (list == null) return false;
        for (var a : list) {
            if (a.desc.startsWith("Lorg/spongepowered/asm/mixin/")) return true;
        }
        return false;
    }

    public boolean isUnique(org.objectweb.asm.tree.AnnotationNode a) {
        return a != null && a.desc.equals("Lorg/spongepowered/asm/mixin/Unique;");
    }

    public boolean hasPackagePrivateMembers(ClassNode cn) {
        for (var m : cn.methods) {
            if ((m.access & (org.objectweb.asm.Opcodes.ACC_PUBLIC
                    | org.objectweb.asm.Opcodes.ACC_PRIVATE
                    | org.objectweb.asm.Opcodes.ACC_PROTECTED)) == 0) return true;
        }
        for (var f : cn.fields) {
            if ((f.access & (org.objectweb.asm.Opcodes.ACC_PUBLIC
                    | org.objectweb.asm.Opcodes.ACC_PRIVATE
                    | org.objectweb.asm.Opcodes.ACC_PROTECTED)) == 0) return true;
        }
        return false;
    }
}
